import { readFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';

const hasOwn = (object, property) =>
  Object.prototype.hasOwnProperty.call(object, property);

function invalidInput() {
  throw new Error('Invalid context packet input');
}

function validateAndFrame(sections, maxBytes) {
  if (!Number.isSafeInteger(maxBytes) || maxBytes < 0 || !Array.isArray(sections)) {
    invalidInput();
  }

  const seenIds = new Set();
  const entries = [];

  for (let index = 0; index < sections.length; index += 1) {
    // `in` alone would accept inherited array elements, which are still holes.
    if (!hasOwn(sections, index)) invalidInput();

    const section = sections[index];
    if (section === null || typeof section !== 'object' || Array.isArray(section)) {
      invalidInput();
    }
    if (!hasOwn(section, 'id') || !hasOwn(section, 'text') ||
        !hasOwn(section, 'priority') || !hasOwn(section, 'required')) {
      invalidInput();
    }

    const { id, text, priority, required } = section;
    if (typeof id !== 'string' || id.length === 0 || typeof text !== 'string' ||
        !Number.isSafeInteger(priority) || priority < 0 || typeof required !== 'boolean' ||
        seenIds.has(id)) {
      invalidInput();
    }

    seenIds.add(id);
    const frame = '### ' + JSON.stringify(id) + '\n' + text + '\n';
    entries.push({ id, priority, required, index, frame, bytes: Buffer.byteLength(frame, 'utf8') });
  }

  return entries;
}

/** Pack complete evidence frames into a byte budget. */
export function packContext(sections, maxBytes) {
  // Build every frame while validating, before considering the budget.
  const entries = validateAndFrame(sections, maxBytes);
  const includedEntries = [];
  let bytes = 0;

  for (const entry of entries) {
    if (entry.required) {
      if (entry.bytes > maxBytes - bytes) {
        throw new Error('Required sections exceed maxBytes');
      }
      includedEntries.push(entry);
      bytes += entry.bytes;
    }
  }

  const optionalByPriority = entries
    .filter((entry) => !entry.required)
    .sort((left, right) => right.priority - left.priority || left.index - right.index);
  const includedOptional = new Set();

  for (const entry of optionalByPriority) {
    if (entry.bytes <= maxBytes - bytes) {
      includedEntries.push(entry);
      includedOptional.add(entry);
      bytes += entry.bytes;
    }
  }

  return {
    text: includedEntries.map((entry) => entry.frame).join(''),
    bytes,
    included: includedEntries.map((entry) => entry.id),
    omitted: entries.filter((entry) => !entry.required && !includedOptional.has(entry))
      .map((entry) => entry.id),
  };
}

function runCli() {
  if (process.argv.length !== 3) {
    throw new Error('Usage: node context-packet.js INPUT_JSON_FILE');
  }

  const input = JSON.parse(readFileSync(process.argv[2], 'utf8'));
  if (input === null || typeof input !== 'object' || Array.isArray(input)) invalidInput();
  const result = packContext(input.sections, input.maxBytes);
  process.stdout.write(JSON.stringify(result) + '\n');
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  try {
    runCli();
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Invalid context packet input';
    process.stderr.write((message || 'Invalid context packet input') + '\n');
    process.exitCode = 2;
  }
}

